function arabicWhatsAppMessage(message){const prefix='Bonjour MK Quincaillerie, ';let text=message;if(text.startsWith(prefix))text=text.slice(prefix.length);const interest=text.match(/^je suis intéressé par : (.+) \(([^)]+)\)\. Pouvez-vous m'indiquer le prix et la disponibilité \?$/);if(interest)return `أنا مهتم بـ: ${translateArabic(interest[1])} (${interest[2]}). هل يمكنكم إخباري بالسعر والتوفر؟`;const quote=text.match(/^je souhaite demander un devis pour : (.+) \(([^)]+)\)\.$/);if(quote)return `أرغب في طلب عرض سعر لـ: ${translateArabic(quote[1])} (${quote[2]}).`;return `${prefix===message?'':'مرحباً أدوات وتجهيزات MK، '}${translateArabic(text)}`}
let currentLanguage=localStorage.getItem('mk-language')==='ar'?'ar':'fr';
function translateArabic(value){if(value.startsWith('Référence :'))return `الرقم المرجعي: ${value.slice('Référence :'.length).trim()}`;return arabicTranslations[value]||value}
function applyWhatsAppLanguage(root=document.body){root.querySelectorAll('a[href*="wa.me/"]').forEach(link=>{const url=new URL(link.href);if(!Object.prototype.hasOwnProperty.call(link,'__frenchWhatsAppMessage'))link.__frenchWhatsAppMessage=url.searchParams.get('text')||'';url.searchParams.set('text',currentLanguage==='ar'?arabicWhatsAppMessage(link.__frenchWhatsAppMessage):link.__frenchWhatsAppMessage);link.href=url.toString()})}
function applyLanguage(root=document.body){const isArabic=currentLanguage==='ar';document.documentElement.lang=isArabic?'ar':'fr';document.documentElement.dir=isArabic?'rtl':'ltr';document.title=isArabic?'أدوات وتجهيزات MK — الأدوات ومستلزمات البناء':'MK Quincaillerie — Outillage & Quincaillerie';const description=document.querySelector('meta[name="description"]');if(description)description.content=isArabic?'أدوات ومستلزمات وتجهيزات لمشاريعكم المهنية والشخصية. تصفحوا كتالوج MK وتواصلوا معنا عبر واتساب.':'MK Quincaillerie — outillage, quincaillerie et équipements. Découvrez notre catalogue et contactez-nous sur WhatsApp.';const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){if(!node.__frenchText)node.__frenchText=node.nodeValue;const source=node.__frenchText;const trimmed=source.trim();if(trimmed){const translated=isArabic?translateArabic(trimmed):trimmed;node.nodeValue=source.replace(trimmed,translated)}}root.querySelectorAll('[placeholder],[aria-label],[alt]').forEach(element=>{['placeholder','aria-label','alt'].forEach(attribute=>{if(!element.hasAttribute(attribute))return;const key=`__french_${attribute}`;if(!element[key])element[key]=element.getAttribute(attribute);const value=element[key];element.setAttribute(attribute,isArabic?translateArabic(value):value)})});const button=document.getElementById('languageToggle');if(button){button.textContent=isArabic?'Français':'العربية';button.setAttribute('aria-label',isArabic?'التبديل إلى الفرنسية':'Passer en arabe')}}
function toggleLanguage(){currentLanguage=currentLanguage==='fr'?'ar':'fr';localStorage.setItem('mk-language',currentLanguage);applyLanguage();applyWhatsAppLanguage()}
function wa(message){const num=CONFIG.whatsappNumber;if(num.includes('X')){alert('Ajoutez le numéro WhatsApp de MK dans app.js : CONFIG.whatsappNumber');return '#'}return `https://wa.me/${num}?text=${encodeURIComponent(message)}`}
function productCard(p){return `<article class="product"><a href="product.html?id=${p.id}"><div class="product-img"><img src="${p.img}" alt="${p.name}" loading="lazy" onerror="this.onerror=null;this.src='assets/favicon.svg';this.classList.add('image-fallback');this.parentElement.classList.add('image-fallback-container')">${p.badge?`<span class="badge">${p.badge}</span>`:''}</div><div class="product-body"><div class="product-cat">${p.category}</div><h3>${p.name}</h3><p>${p.desc}</p><div class="product-foot"><a class="btn btn-dark btn-small" href="product.html?id=${p.id}">Détails</a><a class="btn btn-whatsapp btn-small" href="${wa(`Bonjour MK Quincaillerie, je suis intéressé par : ${p.name} (${p.ref}). Pouvez-vous m'indiquer le prix et la disponibilité ?`)}" target="_blank">WhatsApp</a></div></div></article>`}
function categoryCard(c){return `<a class="cat" href="products.html?category=${encodeURIComponent(c[0])}"><div class="icon">${c[2]}</div><h3>${c[0]}</h3><p>${c[1]}</p></a>`}
function header(active=''){return `<div class="topbar"><div class="container"><span>✓ Conseil professionnel</span><span>✓ Demande de devis</span><span><b>WhatsApp</b> — commande rapide</span></div></div><header><div class="container nav"><a class="brand" href="index.html"><img src="assets/logo-mk.jpg" alt="MK Quincaillerie"></a><nav class="navlinks"><a class="${active==='home'?'active':''}" href="index.html">Accueil</a><a class="${active==='products'?'active':''}" href="products.html">Produits</a><a class="${active==='categories'?'active':''}" href="categories.html">Catégories</a><a class="${active==='services'?'active':''}" href="services.html">Services</a><a class="${active==='about'?'active':''}" href="about.html">À propos</a><a class="${active==='contact'?'active':''}" href="contact.html">Contact</a></nav><div class="nav-actions"><button class="language-toggle" id="languageToggle" onclick="toggleLanguage()" aria-label="التبديل إلى العربية">العربية</button><button class="search-btn" onclick="toggleSearch()" aria-label="Rechercher">⌕</button><a class="btn btn-primary btn-small" href="${wa('Bonjour MK Quincaillerie, je souhaite obtenir des informations sur vos produits.') }" target="_blank">WhatsApp</a></div><button class="menu" onclick="toggleMenu()" aria-label="Menu">☰</button></div><div id="mobileMenu" class="container" style="display:none;padding:0 0 16px"><nav style="display:grid;gap:12px"><a href="index.html">Accueil</a><a href="products.html">Produits</a><a href="categories.html">Catégories</a><a href="services.html">Services</a><a href="about.html">À propos</a><a href="contact.html">Contact</a></nav></div><div id="searchPanel" class="search-panel"><div class="container"><input id="globalSearch" onkeydown="if(event.key==='Enter') location.href='products.html?q='+encodeURIComponent(this.value)" placeholder="Rechercher un produit, une catégorie ou une référence…"></div></div></header>`}
function footer(){return `<footer><div class="container footer-grid"><div class="footer-brand"><img src="assets/logo-mk.jpg" alt="MK Quincaillerie"><p>Votre partenaire pour l’outillage, la quincaillerie et les équipements. Un catalogue clair, un conseil humain et une commande simple par WhatsApp.</p><a class="btn btn-whatsapp" href="${wa('Bonjour MK Quincaillerie, je souhaite obtenir des informations.') }" target="_blank">Discuter sur WhatsApp</a></div><div class="footer-col"><h4>Navigation</h4><a href="index.html">Accueil</a><a href="products.html">Produits</a><a href="categories.html">Catégories</a><a href="services.html">Services</a><a href="about.html">À propos</a><a href="contact.html">Contact</a></div><div class="footer-col"><h4>Catégories</h4><a href="products.html?category=Outillage%20électroportatif">Outillage</a><a href="products.html?category=Visserie%20%26%20fixation">Visserie & fixation</a><a href="products.html?category=Peinture%20%26%20accessoires">Peinture</a><a href="products.html?category=Électricité">Électricité</a><a href="products.html?category=Plomberie">Plomberie</a></div><div class="footer-col"><h4>Contact</h4><a href="${wa('Bonjour MK Quincaillerie.') }" target="_blank">WhatsApp</a><a href="${CONFIG.mapsUrl}" target="_blank">Google Maps</a><a href="contact.html">Adresse & horaires</a><a href="contact.html">Informations pratiques</a></div></div><div class="container copyright"><span>© 2026 MK Quincaillerie. Tous droits réservés.</span><span>Catalogue professionnel • Commande par WhatsApp</span></div></footer><a class="floating-wa" href="${wa('Bonjour MK Quincaillerie, j’ai besoin d’aide pour trouver un produit.') }" target="_blank">◉ WhatsApp · Besoin d’aide ?</a>`}
function shell(content,active=''){document.getElementById('app').innerHTML=header(active)+content+footer();applyLanguage(document.getElementById('app'));applyWhatsAppLanguage(document.getElementById('app'))}
function toggleSearch(){document.getElementById('searchPanel').classList.toggle('open');if(document.getElementById('searchPanel').classList.contains('open'))document.getElementById('globalSearch').focus()}
function toggleMenu(){const x=document.getElementById('mobileMenu');x.style.display=x.style.display==='none'?'block':'none'}
function hero(){return `<section class="hero"><div class="slide active"><div class="slide-bg" style="background-image:url('https://images.unsplash.com/photo-1504148455328-c376907d081c?auto=format&fit=crop&w=1800&q=85')"></div><div class="slide-overlay"></div><div class="container slide-content"><span class="eyebrow">MK QUINCAILLERIE</span><h1>Tout pour vos travaux.</h1><p>Outillage, quincaillerie et équipements pour vos projets professionnels et personnels.</p><div class="hero-actions"><a class="btn btn-primary" href="products.html">Découvrir nos produits</a><a class="btn btn-outline" style="border-color:#fff;color:#fff" href="${wa('Bonjour MK Quincaillerie, je souhaite découvrir vos produits.') }" target="_blank">Commander sur WhatsApp</a></div></div></div><div class="slide"><div class="slide-bg" style="background-image:url('https://images.unsplash.com/photo-1530124566582-a618bc2615dc?auto=format&fit=crop&w=1800&q=85')"></div><div class="slide-overlay"></div><div class="container slide-content"><span class="eyebrow">OUTILLAGE</span><h1>Le bon outil pour le bon travail.</h1><p>Découvrez notre sélection d’outillage et d’accessoires pour travailler efficacement.</p><div class="hero-actions"><a class="btn btn-primary" href="products.html?category=Outillage%20électroportatif">Voir l’outillage</a><a class="btn btn-outline" style="border-color:#fff;color:#fff" href="${wa('Bonjour MK Quincaillerie, je souhaite un conseil pour choisir un outil.') }" target="_blank">Demander un conseil</a></div></div></div><div class="slide"><div class="slide-bg" style="background-image:url('https://images.unsplash.com/photo-1586864387967-d02ef85d93e8?auto=format&fit=crop&w=1800&q=85')"></div><div class="slide-overlay"></div><div class="container slide-content"><span class="eyebrow">BESOIN SPÉCIFIQUE</span><h1>Vous cherchez un produit précis ?</h1><p>Envoyez-nous une photo ou décrivez votre besoin. Notre équipe vous aide à trouver la solution adaptée.</p><div class="hero-actions"><a class="btn btn-primary" href="${wa('Bonjour MK Quincaillerie, je recherche un produit précis. Je vais vous envoyer une photo ou une description.') }" target="_blank">Envoyer une photo</a><a class="btn btn-outline" style="border-color:#fff;color:#fff" href="${wa('Bonjour MK Quincaillerie, je souhaite demander un devis.') }" target="_blank">Demander un devis</a></div></div></div><div class="carousel-controls"><button onclick="changeSlide(-1)">‹</button><button onclick="changeSlide(1)">›</button></div><div class="dots"><button class="active" onclick="goSlide(0)"></button><button onclick="goSlide(1)"></button><button onclick="goSlide(2)"></button></div></section>`}
let slideIndex=0;let slideTimer;function initHero(){if(!document.querySelector('.hero'))return;slideTimer=setInterval(()=>changeSlide(1),6000)}function goSlide(n){const slides=document.querySelectorAll('.slide'),dots=document.querySelectorAll('.dots button');slideIndex=(n+slides.length)%slides.length;slides.forEach((s,i)=>s.classList.toggle('active',i===slideIndex));dots.forEach((d,i)=>d.classList.toggle('active',i===slideIndex))}function changeSlide(d){goSlide(slideIndex+d);clearInterval(slideTimer);slideTimer=setInterval(()=>changeSlide(1),6000)}
function home(){shell(`${hero()}<section class="section"><div class="container"><div class="section-head"><div><div class="kicker">Trouver rapidement</div><h2>Nos catégories</h2></div><p>Une sélection organisée pour vous aider à trouver le bon produit sans perdre de temps.</p></div><div class="categories">${categories.map(categoryCard).join('')}</div></div></section><section class="section" style="padding-top:10px"><div class="container"><div class="section-head"><div><div class="kicker">Sélection MK</div><h2>Produits vedettes</h2></div><a class="btn btn-dark" href="products.html">Voir tout le catalogue</a></div><div class="products">${products.filter(p=>p.featured).map(productCard).join('')}</div></div></section><section class="section"><div class="container"><div class="split"><div class="dark-panel"><div class="kicker" style="color:#ffb000">Service humain</div><h2>Vous ne connaissez pas le nom du produit ?</h2><p>Pas de problème. Envoyez-nous une photo ou décrivez votre besoin. Nous vous aidons à identifier le produit et à vérifier sa disponibilité.</p><a class="btn btn-primary" href="${wa('Bonjour MK Quincaillerie, je recherche un produit. Je vais vous envoyer une photo ou une description.') }" target="_blank">📷 Envoyer une photo sur WhatsApp</a></div><div class="light-panel"><div class="kicker">Demande rapide</div><h2>Un besoin professionnel ?</h2><p>Pour une quantité importante ou un besoin spécifique, demandez un devis directement à notre équipe.</p><a class="btn btn-dark" href="${wa('Bonjour MK Quincaillerie, je souhaite demander un devis pour : ') }" target="_blank">Demander un devis</a></div></div></div></section><section class="section" style="padding-top:10px"><div class="container"><div class="section-head"><div><div class="kicker">Pourquoi nous</div><h2>Simple, pratique, professionnel.</h2></div></div><div class="benefits"><div class="benefit"><div class="num">01</div><h3>Large choix</h3><p>Des produits pour les travaux, projets et besoins professionnels.</p></div><div class="benefit"><div class="num">02</div><h3>Conseil</h3><p>Une équipe disponible pour vous orienter vers le produit adapté.</p></div><div class="benefit"><div class="num">03</div><h3>Commande rapide</h3><p>Contactez-nous directement par WhatsApp pour connaître les disponibilités.</p></div><div class="benefit"><div class="num">04</div><h3>Service pro</h3><p>Une approche adaptée aux particuliers comme aux professionnels.</p></div></div></div></section><section class="section"><div class="container"><div class="section-head"><div><div class="kicker">Avis</div><h2>Ce que pensent nos clients</h2></div></div><div class="reviews"><div class="review"><div class="stars">★★★★★</div><p>Ajoutez ici un avis réel provenant de vos clients.</p><small>Client MK Quincaillerie</small></div><div class="review"><div class="stars">★★★★★</div><p>Ajoutez ici un second avis réel pour renforcer la confiance.</p><small>Client MK Quincaillerie</small></div><div class="review"><div class="stars">★★★★★</div><p>Les avis peuvent être remplacés facilement dans les données du site.</p><small>Client MK Quincaillerie</small></div></div></div></section><section class="section" style="padding-top:10px"><div class="container"><div class="cta"><div><div class="kicker" style="color:#6b4b00">MK QUINCAILLERIE</div><h2>Un produit, une quantité ou un devis ?</h2><p>Contactez-nous directement et parlons de votre besoin.</p></div><a class="btn btn-dark" href="${wa('Bonjour MK Quincaillerie, je souhaite obtenir un devis ou des informations.') }" target="_blank">Parler sur WhatsApp</a></div></div></section><section class="section"><div class="container"><div class="section-head"><div><div class="kicker">Localisation</div><h2>Retrouvez-nous</h2><p>Consultez notre emplacement sur Google Maps.</p></div></div><div class="location"><div class="map-card"><div class="map-grid"></div><div class="pin"><span>●</span></div></div><div class="contact-box"><div class="contact-row"><div>📍</div><div><b>Adresse</b><span>À compléter avec l’adresse officielle de MK Quincaillerie.</span></div></div><div class="contact-row"><div>💬</div><div><b>WhatsApp</b><span>Numéro à renseigner dans app.js.</span></div></div><div class="contact-row"><div>🕒</div><div><b>Horaires</b><span>À compléter avec les horaires officiels.</span></div></div><a class="btn btn-dark" href="${CONFIG.mapsUrl}" target="_blank" style="margin-top:18px">Voir sur Google Maps</a></div></div></div></section>`,`home`);initHero()}
function pageHero(title,desc){return `<section class="page-hero"><div class="container"><div class="kicker" style="color:#ffb000">MK QUINCAILLERIE</div><h1 style="font-size:52px">${title}</h1><p>${desc}</p></div></section>`}
function productsPage(){const params=new URLSearchParams(location.search);const q=(params.get('q')||'').toLowerCase();const cat=params.get('category')||'';shell(`${pageHero('Nos produits','Explorez notre catalogue et trouvez rapidement le produit adapté à votre besoin.')}<section class="section"><div class="container"><div class="catalog-layout"><aside class="filters"><h4>Catégories</h4><label class="filter"><input type="radio" name="cat" value="" ${!cat?'checked':''}> Toutes</label>${categories.map(c=>`<label class="filter"><input type="radio" name="cat" value="${c[0]}" ${cat===c[0]?'checked':''}> ${c[0]}</label>`).join('')}<div style="margin-top:18px;padding-top:16px;border-top:1px solid var(--line)"><a class="btn btn-whatsapp" style="width:100%" href="${wa('Bonjour MK Quincaillerie, je ne trouve pas mon produit dans le catalogue et j’ai besoin d’aide.') }" target="_blank">Produit introuvable ?</a></div></aside><main><div class="catalog-toolbar"><input id="productSearch" value="${q.replace(/"/g,'&quot;')}" placeholder="Rechercher un produit, une référence…"><select id="sort"><option value="default">Trier par défaut</option><option value="name">Nom A–Z</option></select></div><div id="productGrid" class="products"></div></main></div></div></section>`,`products`);renderProducts(q,cat);document.querySelectorAll('input[name="cat"]').forEach(x=>x.addEventListener('change',()=>{const u=new URL(location);u.searchParams.set('category',x.value);if(!x.value)u.searchParams.delete('category');location.href=u}));document.getElementById('productSearch').addEventListener('input',e=>renderProducts(e.target.value.toLowerCase(),document.querySelector('input[name="cat"]:checked').value));document.getElementById('sort').addEventListener('change',e=>{if(e.target.value==='name'){products.sort((a,b)=>a.name.localeCompare(b.name));renderProducts(document.getElementById('productSearch').value.toLowerCase(),document.querySelector('input[name="cat"]:checked').value)}})}
function renderProducts(q='',cat=''){const grid=document.getElementById('productGrid');let arr=products.filter(p=>(!q||[p.name,p.category,p.ref,p.desc,translateArabic(p.name),translateArabic(p.category),translateArabic(p.desc)].join(' ').toLowerCase().includes(q))&&(!cat||p.category===cat));grid.innerHTML=arr.length?arr.map(productCard).join(''):`<div class="empty">Aucun produit trouvé.<br><br><a class="btn btn-whatsapp" href="${wa('Bonjour MK Quincaillerie, je recherche un produit qui n’apparaît pas dans le catalogue.') }" target="_blank">Demander de l’aide sur WhatsApp</a></div>`;applyLanguage(grid);applyWhatsAppLanguage(grid)}
function categoriesPage(){shell(`${pageHero('Nos catégories','Parcourez les familles de produits de MK Quincaillerie.')}<section class="section"><div class="container"><div class="categories">${categories.map(categoryCard).join('')}</div></div></section>`,`categories`)}
function servicesPage(){shell(`${pageHero('Nos services','Plus qu’un catalogue : un accompagnement simple pour trouver et commander le bon produit.')}<section class="section"><div class="container"><div class="benefits"><div class="benefit"><div class="num">01</div><h3>Conseil produit</h3><p>Décrivez votre besoin et demandez conseil avant de choisir.</p><a class="btn btn-dark btn-small" href="${wa('Bonjour MK Quincaillerie, j’ai besoin d’un conseil pour choisir un produit.') }" target="_blank">Demander conseil</a></div><div class="benefit"><div class="num">02</div><h3>Demande de devis</h3><p>Pour vos besoins professionnels ou quantités importantes.</p><a class="btn btn-dark btn-small" href="${wa('Bonjour MK Quincaillerie, je souhaite demander un devis.') }" target="_blank">Demander un devis</a></div><div class="benefit"><div class="num">03</div><h3>Commande WhatsApp</h3><p>Un moyen direct de demander prix et disponibilité.</p><a class="btn btn-whatsapp btn-small" href="${wa('Bonjour MK Quincaillerie, je souhaite commander un produit.') }" target="_blank">WhatsApp</a></div><div class="benefit"><div class="num">04</div><h3>Recherche de produit</h3><p>Vous ne connaissez pas le nom ? Envoyez une photo ou une description.</p><a class="btn btn-dark btn-small" href="${wa('Bonjour MK Quincaillerie, je recherche un produit et je vais vous envoyer une photo.') }" target="_blank">Envoyer une photo</a></div></div></div></section>`,`services`)}
function aboutPage(){shell(`${pageHero('À propos de MK Quincaillerie','Une présence digitale pensée pour présenter les produits clairement et faciliter le contact avec l’équipe.')}<section class="section"><div class="container"><div class="split"><div class="light-panel"><div class="kicker">Notre activité</div><h2>Le produit au centre.</h2><p>MK Quincaillerie propose une sélection de produits et d’équipements destinés aux travaux, au bricolage et aux besoins professionnels.</p><p>Cette page est volontairement construite pour accueillir les informations officielles de l’entreprise sans inventer son histoire, ses certifications ou ses dates.</p></div><div class="dark-panel"><div class="kicker" style="color:#ffb000">Notre approche</div><h2>Simple. Directe. Humaine.</h2><p>Le site facilite la recherche d’un produit, la demande de prix, le devis et la mise en relation via WhatsApp.</p><a class="btn btn-primary" href="products.html">Explorer le catalogue</a></div></div></div></section>`,`about`)}
function contactPage(){shell(`${pageHero('Contactez-nous','Une question, un produit à rechercher ou une demande de devis ?')}<section class="section"><div class="container"><div class="location"><div class="contact-box"><h2>Parlons de votre besoin.</h2><p style="color:var(--muted)">Les coordonnées officielles peuvent être renseignées dans cette section avant mise en ligne.</p><div class="contact-row"><div>💬</div><div><b>WhatsApp</b><span>Numéro à configurer dans app.js</span></div></div><div class="contact-row"><div>📍</div><div><b>Google Maps</b><span>Accès direct à l’emplacement partagé.</span></div></div><div class="contact-row"><div>🕒</div><div><b>Horaires</b><span>À compléter</span></div></div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:20px"><a class="btn btn-whatsapp" href="${wa('Bonjour MK Quincaillerie, je souhaite vous contacter.') }" target="_blank">WhatsApp</a><a class="btn btn-dark" href="${CONFIG.mapsUrl}" target="_blank">Google Maps</a></div></div><div class="map-card"><div class="map-grid"></div><div class="pin"><span>●</span></div></div></div></div></section>`,`contact`)}
function productPage(){const id=new URLSearchParams(location.search).get('id');const p=products.find(x=>x.id===id)||products[0];const specs=Object.entries(p.specs).map(([k,v])=>`<div class="spec"><span>${k}</span><b>${v}</b></div>`).join('');shell(`${pageHero('Détail produit','Informations produit, caractéristiques et contact direct avec MK Quincaillerie.')}<section class="section"><div class="container"><div class="product-detail"><div class="gallery-main"><img src="${p.img}" alt="${p.name}" onerror="this.onerror=null;this.src='assets/favicon.svg';this.classList.add('image-fallback');this.parentElement.classList.add('image-fallback-container')"></div><div class="detail-card"><div class="product-cat">${p.category}</div><h1>${p.name}</h1><div class="ref">Référence : ${p.ref}</div><p style="color:var(--muted);font-size:17px;margin-top:22px">${p.desc}</p><div class="detail-price">Prix sur demande</div><div class="specs">${specs}</div><div class="detail-actions"><a class="btn btn-whatsapp" href="${wa(`Bonjour MK Quincaillerie, je suis intéressé par le produit : ${p.name} (${p.ref}). Pouvez-vous m’indiquer le prix et la disponibilité ?`) }" target="_blank">Commander sur WhatsApp</a><a class="btn btn-dark" href="${wa(`Bonjour MK Quincaillerie, je souhaite demander un devis pour : ${p.name} (${p.ref}).`) }" target="_blank">Demander un devis</a></div></div></div></div></section><section class="section" style="padding-top:0"><div class="container"><div class="section-head"><div><div class="kicker">À découvrir</div><h2>Produits similaires</h2></div></div><div class="products">${products.filter(x=>x.id!==p.id&&x.category===p.category).slice(0,4).map(productCard).join('')||products.filter(x=>x.id!==p.id).slice(0,4).map(productCard).join('')}</div></div></section>`,'products')}
function init(){const path=location.pathname.split('/').pop()||'index.html';if(path==='index.html'||path===''){home()}else if(path==='products.html'){productsPage()}else if(path==='categories.html'){categoriesPage()}else if(path==='services.html'){servicesPage()}else if(path==='about.html'){aboutPage()}else if(path==='contact.html'){contactPage()}else if(path==='product.html'){productPage()}else{home()}}
init();
